INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('c9814ea28393cd16', 'standard-fijian', 'word', 'Balabala', 'balabala', 'noun', 'A thin stick used to scratch or arrange the hair, often made from a balabala tree. This is a historical use; balabala also names a tree fern.', '', '', '', 'English draft reconstructed from the complete historical page and checked against other lexical references where a matching sense was found. Usage and wording remain open to NAISEMA team review.', '{"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"English draft reconstructed from the complete historical page and checked against other lexical references where a matching sense was found. Usage and wording remain open to NAISEMA team review."}}', '[{"sourceId":"a2056948d246","page":16}]', '[]', 'balabala | a thin stick used to scratch or arrange the hair, often made from a balabala tree. this is a historical use; balabala also names a tree fern. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
