INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('a7e4558cd9ce5acf', 'standard-fijian', 'word', 'Bila', 'bila', 'noun', 'A traditional Fijian bread; historically made with ivi nuts and also made from other starchy foods.', '', '', '', 'Ingredients can vary. A historical judgement about bread quality is not part of this word’s meaning.', '{"furtherLink":{"label":"Explore Bila in Kaikki · Fijian bila","href":"https://kaikki.org/dictionary/Fijian/meaning/b/bi/bila.html"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Photographed page 19 mentions ivi. A modern lexical source reports other ingredients. The historical source calls it inferior bread, which is a judgement, not part of the meaning."}}', '[{"sourceId":"a2056948d246","page":19},{"sourceId":"bila-kaikki"}]', '[]', 'bila | a traditional fijian bread; historically made with ivi nuts and also made from other starchy foods. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
