INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('641af6a8bca639da', 'standard-fijian', 'word', 'Bui', 'bui', 'noun', 'An older woman or grandmother; also used in the phrase bui ni gone.', '', '', '', 'Photographed page 23 gives both expressions; an independent historical handbook gives bui as grandmother. Whether bui alone is an appropriate current form of address needs review.', '{"furtherLink":{"label":"Explore Bui in Handbook of the Fijian Language · bui","href":"https://upload.wikimedia.org/wikipedia/commons/f/fb/Handbook_of_the_Fijian_language_%28IA_handbookoffijian00moorrich%29.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Photographed page 23 gives both expressions; an independent historical handbook gives bui as grandmother. Whether bui alone is an appropriate current form of address needs review."}}', '[{"sourceId":"a2056948d246","page":23},{"sourceId":"bui-moore"}]', '[]', 'bui | an older woman or grandmother; also used in the phrase bui ni gone. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
