INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('0dbef27bd48880da', 'standard-fijian', 'word', 'Buka', 'buka', 'noun', 'Fire or firewood, according to context.', '', '', '', 'Photographed page 24 gives both uses; comparative vocabulary also records buka for fire. Keep the fuel and burning senses visible.', '{"furtherLink":{"label":"Explore Buka in Austronesian Basic Vocabulary Database · fire","href":"https://abvd.eva.mpg.de/austronesian/word.php?v=143"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Photographed page 24 gives both uses; comparative vocabulary also records buka for fire. Keep the fuel and burning senses visible."}}', '[{"sourceId":"a2056948d246","page":24},{"sourceId":"bukawaqa-abvd"}]', '[]', 'buka | fire or firewood, according to context. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
