INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('c51378433d633095', 'standard-fijian', 'word', 'Bure', 'bure', 'noun', 'A traditional spirit house or temple, especially in the phrase bure kalou.', '', '', '', 'Photographed page 25 identifies a house associated with a deity. Te Papa independently describes bure kalou as a pre-Christian Fijian spirit house. Bure in other contexts can mean a house, so this is a context-specific sense.', '{"furtherLink":{"label":"Explore Bure in Te Papa · Bure kalou spirit house","href":"https://collections.tepapa.govt.nz/object/206948"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Photographed page 25 identifies a house associated with a deity. Te Papa independently describes bure kalou as a pre-Christian Fijian spirit house. Bure in other contexts can mean a house, so this is a context-specific sense."}}', '[{"sourceId":"a2056948d246","page":25},{"sourceId":"bure-tepapa"}]', '[]', 'bure | a traditional spirit house or temple, especially in the phrase bure kalou. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
