INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('26c1257c875bd6df', 'standard-fijian', 'word', 'Bure', 'bure', 'noun', 'A communal house where unmarried men and visitors slept, also called a bure ni sa in older usage.', '', '', '', 'The pattern says bure ni sa, not bure ni ta. Fiji Times independently describes this historical institution. General traditional house and spirit-house uses remain separate.', '{"furtherLink":{"label":"Explore Bure in The Fiji Times · Bure ni sa history","href":"https://www.fijitimes.com.fj/discovering-fiji-a-sickly-child-abstinence-and-mens-only-bure/"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"The photographed page says bure ni sa, not bure ni ta. Fiji Times independently describes this historical institution. General traditional house and spirit-house uses remain separate."}}', '[{"sourceId":"a2056948d246","page":26},{"sourceId":"bure-ni-sa-fiji-times"}]', '[]', 'bure | a communal house where unmarried men and visitors slept, also called a bure ni sa in older usage. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('366d4545a34a7fa0', 'standard-fijian', 'word', 'Bure', 'bure', 'noun', 'A traditional counting unit of ten clubs.', '', '', '', 'Photographed page 26 and an independent Fiji Times count agree. This is separate from the house senses.', '{"furtherLink":{"label":"Explore Bure in The Fiji Times · Traditional counting units","href":"https://www.fijitimes.com.fj/keeping-alive-a-unique-way-of-life/"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Photographed page 26 and an independent Fiji Times count agree. This is separate from the house senses."}}', '[{"sourceId":"a2056948d246","page":26},{"sourceId":"counting-fiji-times"}]', '[]', 'bure | a traditional counting unit of ten clubs. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
