INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('41d96e46750ec3e7', 'standard-fijian', 'word', 'Buroro', 'buroro', 'verb', 'To sprout or shoot up again, as grass after burning or damage.', '', '', '', 'Photographed page 26 gives regrowth after burning or destruction. No independent present-day usage example has been located.', '{"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Photographed page 26 gives regrowth after burning or destruction. No independent present-day usage example has been located."}}', '[{"sourceId":"a2056948d246","page":26}]', '[]', 'buroro | to sprout or shoot up again, as grass after burning or damage. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
