INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('c17984d1044dc82d', 'standard-fijian', 'word', 'Burotu', 'burotu', 'noun', 'A beautiful place of departed spirits in Fijian tradition; also used figuratively for a delightful place.', '', '', '', 'Photographed page 26 gives the spiritual and proverbial uses. ANU research discusses Burotu traditions. Mythic accounts vary by place and teller.', '{"furtherLink":{"label":"Explore Burotu in ANU Press · Burotu traditions","href":"https://press.anu.edu.au/downloads/press/p289571/html/ch03.xhtml?page=9&referer="},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Photographed page 26 gives the spiritual and proverbial uses. ANU research discusses Burotu traditions. Mythic accounts vary by place and teller."}}', '[{"sourceId":"a2056948d246","page":26},{"sourceId":"burotu-anu"}]', '["colors"]', 'burotu | a beautiful place of departed spirits in fijian tradition; also used figuratively for a delightful place. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
