oads/2017/06/taro.pdf"},"appsSite":{"englishChecked":false,"status":"needs review","notes":"English meaning and example cross-checked; example translation confirmed by the NAISEMA owner. Tuvavosa roles and sense wording still need team review."}}', '[{"sourceId":"a2056948d246","page":108},{"sourceId":"spc-rourou-taro"},{"sourceId":"anu-fiji-crop-names"}]', '["edible-greens","food","plants"]', 'rourou | taro (dalo) leaves, especially when prepared as food. | | | leafy greens | taro leaves | vegetable leaves', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
